function validate([operations, args]) {
  if (operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'TopVotedCandidate' || !Array.isArray(args[0]) || args[0].length !== 2) return 'Start with TopVotedCandidate(persons, times).';
  const [persons, times] = args[0];
  const n = persons.length;
  if (n < 1 || n > 5000) return 'persons needs 1 to 5000 votes.';
  if (times.length !== n) return 'persons and times need the same length.';
  if (persons.some(p => !Number.isInteger(p) || p < 0 || p >= n)) return 'Each candidate is a whole number from 0 to persons.length - 1.';
  if (times.some(x => !Number.isInteger(x) || x < 0 || x > 1000000000)) return 'Each time is a whole number from 0 to 10^9.';
  for (let i = 1; i < n; i++) if (times[i] <= times[i - 1]) return 'times must be strictly increasing.';
  if (operations.length - 1 > 10000) return 'At most 10^4 calls to q.';
  for (let i = 1; i < operations.length; i++) {
    if (operations[i] !== 'q') return 'Only q can follow the constructor.';
    const [t] = args[i];
    if (args[i].length !== 1 || !Number.isInteger(t)) return 'q takes one whole number.';
    if (t < times[0] || t > 1000000000) return 'Each query time is between times[0] and 10^9.';
  }
  return null;
}

