class TopVotedCandidate {
  constructor(persons, times) {
    this.times = times;
    this.leaders = [];
    const counts = new Array(persons.length).fill(0);
    let leader = persons[0];
    for (const person of persons) {
      counts[person]++;
      if (counts[person] >= counts[leader]) {
        leader = person;
      }
      this.leaders.push(leader);
    }
  }

  q(t) {
    let left = 0;
    let right = this.times.length - 1;
    while (left < right) {
      const mid = Math.floor((left + right + 1) / 2);
      if (this.times[mid] <= t) {
        left = mid;
      } else {
        right = mid - 1;
      }
    }
    return this.leaders[left];
  }
}

