class TopVotedCandidate {
  constructor(persons, times) {
    this.persons = persons.slice();
    this.times = times.slice();
  }
  q(t) {
    const count = new Map();
    const last = new Map();
    for (let i = 0; i < this.times.length; i++) {
      if (this.times[i] > t) continue;
      const p = this.persons[i];
      count.set(p, (count.get(p) || 0) + 1);
      last.set(p, this.times[i]);
    }
    let best = -1;
    for (const [p, c] of count) {
      if (best === -1 || c > count.get(best) || (c === count.get(best) && last.get(p) > last.get(best))) best = p;
    }
    return best;
  }
}

