function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 2000 : 1 + Math.floor(rand() * 8);
  const pool = large ? (rand() < 0.5 ? 3 : n) : 1 + Math.floor(rand() * Math.min(n, 3));
  const persons = Array.from({ length: n }, () => Math.floor(rand() * pool));
  const times = [];
  let time = Math.floor(rand() * (large ? 1000 : 6));
  for (let i = 0; i < n; i++) {
    times.push(time);
    time += 1 + Math.floor(rand() * (large ? 499998 : 5));
  }
  const operations = ['TopVotedCandidate'];
  const args = [[persons, times]];
  const queries = large ? 499 : 1 + Math.floor(rand() * 10);
  for (let i = 0; i < queries; i++) {
    const r = rand();
    let t;
    if (r < 0.4) t = times[Math.floor(rand() * n)];
    else if (r < 0.5) t = rand() < 0.5 ? times[0] : 1000000000;
    else t = times[0] + Math.floor(rand() * (times[n - 1] - times[0] + (large ? 1000 : 6)));
    operations.push('q');
    args.push([Math.min(t, 1000000000)]);
  }
  return [operations, args];
}
